  assetsRoot: string,
  overrides: BuildDefaultDecisionDepsOptions = {},
): DecisionDeps {
  const which = overrides.which ?? defaultWhich;
  const execCapture = overrides.execCapture ?? defaultExecCapture;
  return {
    promptStrategy: defaultPromptStrategy,
    promptFileDecision: defaultPromptFileDecision,
    renderUnifiedDiff: (relPath, kind) =>
      defaultRenderUnifiedDiffForEntry(relPath, kind, {
        target,
        assetsRoot,
        which,
        execCapture,
      }),
    openEditor: (relPath: string) => defaultOpenEditor(relPath, target, assetsRoot),
    sha256Content: defaultSha256Content,
  };
}

/** Optional overrides for `buildDefaultDecisionDeps`. All fields default
 * to the real implementation from `lib/env.js`. Tests use these to inject
 * stubs (e.g. simulate a missing `diff` binary). */
export interface BuildDefaultDecisionDepsOptions {
  which?: (cmd: string) => string | null;
  execCapture?: typeof defaultExecCapture;
}

/**
 * Top-level strategy picker: batch-adopt (default), batch-keep, or per-file.
 *
 * Uses the @inquirer/prompts `select` widget so the user navigates with
 * arrow keys instead of typing a single letter. `select` highlights the
 * default choice by matching `default` against a choice's `value`, so the
 * `default` string must be one of the `value`s below — not a letter key
 * or an index.
 */
async function defaultPromptStrategy(): Promise<StrategyMode> {
  const result = await select({
    message: "Choose upgrade strategy for interactive files",
    default: "all-adopt",
    choices: [
      {
        name: "Adopt new version for every file (recommended)",
        value: "all-adopt",
        description: "覆盖所有交互区文件（0.1.1 行为）",
      },
      {
        name: "Keep my current files (skip all updates)",
        value: "all-keep",
        description: "保留本地修改，跳过本次新内容",
      },
      {
        name: "Decide per file",
        value: "per-file",
        description: "逐文件查看 diff 后选择",
      },
    ],
  });
  if (result === "all-adopt" || result === "all-keep" || result === "per-file") return result;
  // Defensive: should never happen given the choices above.
  return "all-adopt";
}

/**
 * Per-file decision prompt. The choices vary by `kind` because the user's
 * mental model is different for an existing-but-modified file vs. a brand
 * new file vs. one slated for deletion under --prune.
 *
 * When `remaining > 0` we append two batch entries separated from the
 * base choices by a `Separator`:
 *
 *   - "Adopt all remaining (N)" — collapse every subsequent file to adopt.
 *   - "Keep all remaining (N)" — collapse every subsequent file to keep.
 *
 * The sentinel values `__adopt-all` / `__keep-all` are recognised by
 * `resolveUpgradeActions` to fan the decision out and exit the per-file loop.
 *
 * `select` highlights the default choice by matching `default` against a
 * choice's `value`; descriptions carry the contextual hint. We no longer
 * suffix `(default)` onto the choice name — the renderer renders the
 * highlight directly.
 */
type FileDecisionAnswer = "adopt" | "keep" | "edit" | "__adopt-all" | "__keep-all";

async function defaultPromptFileDecision(
  entry: PlanEntry,
  remaining: number,
  kind: FileKind,
): Promise<FileDecisionAnswer> {
  const header = describeEntry(entry);
  const defaultValue: FileDecisionAnswer = kind === "modified" ? "keep" : "adopt";
  const baseChoices: Array<{ name: string; value: FileDecisionAnswer; description?: string }> =
    kind === "modified"
      ? [
          {
            name: "Adopt new version",
            value: "adopt",
            description: "用新版本覆盖本地",
          },
          {
            name: "Keep my version",
            value: "keep",
            description: "保守保护本地修改",
          },
          {
            name: "Edit / merge manually in $EDITOR",
            value: "edit",
            description: "在 $EDITOR 中合并新版本到本地",
          },
        ]
      : kind === "added"
        ? [
            {
              name: "Adopt new file",
              value: "adopt",
              description: "写入新文件",
            },
            {
              name: "Skip (don't add this file)",
              value: "keep",
              description: "不添加此文件",
            },
          ]
        : [
            {
              name: "Delete (--prune)",
              value: "adopt",
              description: "删除该文件（仅 --prune 时生效）",
            },
            {
              name: "Keep my file",
              value: "keep",
              description: "保留本地副本",
            },
          ];

  const batchChoices: Array<{ name: string; value: FileDecisionAnswer; description: string }> =
    remaining > 0
      ? [
          {
            name: `Adopt all remaining (${remaining})`,
            value: "__adopt-all",
            description: "对剩余 N 个文件全部采用新版本",
          },
          {
            name: `Keep all remaining (${remaining})`,
            value: "__keep-all",
            description: "对剩余 N 个文件全部保留本地",
          },
        ]
      : [];

  const answer = await select<FileDecisionAnswer>({
    message: header,
    default: defaultValue,
    choices:
      batchChoices.length > 0
        ? [...baseChoices, new Separator(), ...batchChoices]
        : baseChoices,
  });
  if (answer === "__adopt-all" || answer === "__keep-all") return answer;
  if (answer === "adopt" || answer === "keep" || answer === "edit") return answer;
  // Defensive: fall back to keep if the prompt somehow returns an unknown value.
  return "keep";
}

function describeEntry(entry: PlanEntry): string {
  const verb = entry.kind === "modified" ? "modified" : entry.kind === "added" ? "added" : "removed";
  return `${entry.relPath} (${verb})`;
}

/**
 * Render a unified diff for the file. Uses the system `diff` CLI when
 * available; otherwise prints the new version's full content under a clear
 * header so the user can still review what would land.
 *
 * Returns the rendered string (also printed to the upgrade log) so callers
 * that want to keep the diff around — e.g. for a `--diff-out` flag — can
 * consume it without re-running `diff`.
 *
 * This is the low-level helper that powers `defaultRenderUnifiedDiffForEntry`
 * (the kind-aware adapter wired into `DecisionDeps`). It is exported so
 * tests can exercise the `diff`/`readFileSync` fallback paths without
 * having to mock the whole `DecisionDeps` surface.
 */
async function defaultRenderUnifiedDiff(
  relPath: string,
  fromAbs: string,
  toAbs: string,
  deps: { which: (cmd: string) => string | null; execCapture: typeof defaultExecCapture } = {
    which: defaultWhich,
    execCapture: defaultExecCapture,
  },
): Promise<string> {
  logger.info(`--- unified diff for ${relPath} ---`);
  if (deps.which("diff") !== null) {
    const result = await deps.execCapture("diff", ["-u", fromAbs, toAbs]);
    const stdout = result.stdout.trim();
    if (stdout.length === 0) {
      logger.info("(files are identical)");
      return "";
    }
    for (const line of stdout.split(/\r?\n/)) logger.info(line);
    if (result.exitCode > 1) {
      // diff exits 1 when files differ — expected. > 1 means actual error.
      logger.warn(`diff exited ${result.exitCode}: ${result.stderr.trim()}`);
    }
    return stdout;
  }
  // Fallback: print the new version in full so the user can still review.
  logger.info("(diff CLI not found; showing new version in full)");
  logger.info("New version from assets:");
  const newContent = readFileSync(toAbs, "utf-8");
  for (const line of newContent.split(/\r?\n/)) logger.info(line);
  return newContent;
}

export { defaultRenderUnifiedDiff };

/**
 * Kind-aware adapter for the per-file diff preview that the decision
 * layer fires BEFORE `promptFileDecision`. Resolves the file kind to the
 * appropriate view using the closures captured by
 * `buildDefaultDecisionDeps`:
 *
 *   - `modified` → unified diff (`diff -u <fromAbs> <toAbs>`) with the
 *      existing fallback when the system `diff` CLI is missing.
 *   - `added`    → just print the new file's contents (there's nothing
 *      to diff against).
 *   - `removed`  → print the file that would be deleted (or a notice
 *      when it's already gone from disk).
 *
 * Errors reading individual files are logged as warnings and the preview
 * returns an empty string — the decision layer swallows the empty
 * response and proceeds to the prompt. This matches requirement #5 of
 * the diff-preview wiring (render failure must not block the prompt).
 */
async function defaultRenderUnifiedDiffForEntry(
  relPath: string,
  kind: FileKind,
  ctx: {
    target: string;
    assetsRoot: string;
    which: (cmd: string) => string | null;
    execCapture: typeof defaultExecCapture;
  },
): Promise<string> {
  if (kind === "modified") {
    const fromAbs = join(ctx.target, relPath);
    const toAbs = join(ctx.assetsRoot, relPath);
    return defaultRenderUnifiedDiff(relPath, fromAbs, toAbs, {
      which: ctx.which,
      execCapture: ctx.execCapture,
    });
  }
  if (kind === "added") {
    const toAbs = join(ctx.assetsRoot, relPath);
    logger.info(`--- new file ${relPath} ---`);
    let content: string;
    try {
      content = readFileSync(toAbs, "utf-8");
    } catch (error) {
      logger.warn(
        `could not read new version of ${relPath}: ${
          error instanceof Error ? error.message : String(error)
        } — skipping preview`,
      );
      return "";
    }
    for (const line of content.split(/\r?\n/)) logger.info(line);
    return content;
  }
  // kind === "removed"
  const oldAbs = join(ctx.target, relPath);
  logger.info(`--- ${relPath} (no longer exists in new version) ---`);
  try {
    const content = readFileSync(oldAbs, "utf-8");
    logger.info("Current content (would be removed when --prune is in effect):");
    for (const line of content.split(/\r?\n/)) logger.info(line);
    return content;
  } catch {
    logger.info("(this file no longer exists on disk either)");
    return "";
  }
}

export { defaultRenderUnifiedDiffForEntry };

/**
 * Open the user's editor on the current file and return whatever they
 * saved. Falls back to logging a warning and returning an empty string
 * (which `resolveUpgradeActions` treats as "keep my version") if the editor
 * is missing or exits non-zero.
 *
 * We pass `waitForUserInput: true` so the prompt does not return until the
 * user closes their editor — without this, @inquirer/editor would resolve
 * immediately with the unchanged default and the user would see nothing
 * happen.
 */
async function defaultOpenEditor(
  relPath: string,
  target: string,
  assetsRoot: string,
): Promise<string> {
  const currentPath = join(target, relPath);
  const newPath = join(assetsRoot, relPath);
  let current = "";
  try {
    current = readFileSync(currentPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read current version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  let incoming = "";
  try {
    incoming = readFileSync(newPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read new version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  logger.info(`--- editing ${relPath} ---`);
  logger.info("New version from assets:");
  for (const line of incoming.split(/\r?\n/)) logger.info(line);
  logger.info("--- end of new version; opening $EDITOR with current content as default ---");

  try {
    const edited = await editor({
      message: `Edit ${relPath} (close the editor when done; an empty file means "keep my version")`,
      default: current,
      postfix: ".md",
      waitForUserInput: true,
    });
    return edited;
  } catch (error) {
    logger.warn(
      `editor failed for ${relPath}: ${error instanceof Error ? error.message : String(error)} — keeping current version`,
    );
    return "";
  }
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

import { copyFileSync, existsSync, rmSync } from "node:fs";
import { execFile } from "node:child_process";
import { dirname, join } from "node:path";
import { promisify } from "node:util";
import { resolveTarget, stateFile, resolveAsset } from "../lib/paths.js";
import { logger } from "../lib/logger.js";
import { diffTree, type PkgInclude, type DiffPlan } from "../lib/diff.js";
import { createBackup } from "../lib/backup.js";
import {
  readAssetsVersion,
  readCliVersion,
  writeState,
  requireState,
  compareVersions,
  StateMissingError,
  type InstallState,
  type ChannelKey,
} from "../lib/version.js";
import { installCodegraph, installEntire } from "../lib/plugins/index.js";
import { copyDir } from "../lib/copy.js";
import { selfUpdate } from "../upgrade/self.js";
import { resolveUpgradeActions, type ResolvedPlan } from "../upgrade/decision.js";
import { buildDefaultDecisionDeps } from "../upgrade/decision-defaults.js";
import { isInteractive } from "../lib/env.js";
import { ensureDir, atomicWriteFile } from "../lib/fs-safe.js";
import { ExitPromptError } from "@inquirer/core";
import type { Channels } from "../lib/ui.js";

const execFileAsync = promisify(execFile);

const NPM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes — codegraph npm install can be slow
const EXEC_MAX_BUFFER = 64 * 1024 * 1024; // 64MB

export interface UpgradeOptions {
  target?: string;
  /** When true, delete files in target that are no longer in assets. */
  prune?: boolean;
  dryRun?: boolean;
  /** Skip the CLI self-update stage entirely. */
  noSelf?: boolean;
  with?: string;
  without?: string;
  /**
   * Explicit user request for interactive prompts. `true` is set by
   * `--interactive`; `false` by `--no-interactive`; `undefined` means
   * "default" — fall through to the tty + yes-based decision in
   * `upgradeCommand`.
   */
  interactive?: boolean;
  /**
   * True when the user explicitly passed `--interactive` or `--no-interactive`
   * on the command line. Distinguishes "user said no" from "user said
   * nothing, the upgrader defaulted". The decision layer uses this to know
   * whether it should warn when the tty-based fallback runs.
   */
  interactiveSetByUser?: boolean;
  /** Suppress all prompts and accept defaults (existing -y / --yes flag). */
  yes?: boolean;
  /**
   * @internal Test seam — pass fake `DecisionDeps` to drive every decision
   * branch without spawning real prompts or editors. Production code does
   * not set this; `buildDefaultDecisionDeps()` is used instead.
   */
  decisionDeps?: import("../upgrade/decision.js").DecisionDeps;
  /**
   * @internal Test seam — force `isInteractiveEnv` to a specific value
   * regardless of the host tty state. Production code does not set this.
   * Useful for integration tests that want to exercise the interactive
   * code path on CI hosts with no tty.
   */
  forceInteractiveEnv?: boolean;
}

/**
 * `pisquad upgrade` — sync a target install with the assets bundled in this
 * CLI package. See `docs/tasks/pisquad-cli/11-upgrade-command.md` for the full
 * behavioural contract.
 */
export async function upgradeCommand(options: UpgradeOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const dryRun = options.dryRun === true;
  logger.info(`pisquad upgrade → ${target}${dryRun ? " (dry-run)" : ""}`);

  // 1. CLI self-update — if we actually upgraded the global CLI, the in-memory
  //    code is stale; tell the user to re-run and exit cleanly.
  let selfResult;
  try {
    selfResult = await selfUpdate({ logger, noSelf: options.noSelf });
  } catch (error) {
    logger.error(
      `CLI self-update failed: ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exitCode = 1;
    return;
  }
  if (selfResult.updated) {
    logger.success(
      "CLI self-updated to latest. Re-run `pisquad upgrade` to sync this project with the new version.",
    );
    return;
  }

  // 2. Require an existing install — legacy bash-installed projects have no
  //    state.json and must reinstall (PRD non-goal #1).
  let state: InstallState;
  try {
    state = requireState(target);
  } catch (error) {
    if (error instanceof StateMissingError) {
      logger.error(error.message);
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  // 3. Decide the post-upgrade channel set: state baseline + flags.
  let newChannels;
  try {
    newChannels = mergeChannels(state.channels, options);
  } catch (error) {
    logger.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
    return;
  }
  const cliVersion = readCliVersion();
  const assetsVersion = readAssetsVersion();
  const versionDiff = compareVersions(state, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
  });

  // 4. Build the diff include list (subtree granularity, never the whole .pi/).
  //    The includes are intentionally narrow so .pi/assets-version.txt and
  //    .pi/.gitignore (root files) never enter the diff.
  //
  //    `interactive: true` flags user-editable territory (docs, agents,
  //    skills). These are eligible for per-file prompts in
  //    `resolveUpgradeActions`. Extension packages are managed by the
  //    pisquad release process — they are always overwritten, never
  //    presented for per-file adoption.
  const includes: PkgInclude[] = [
    { pkgSubPath: ".pi/agents", targetSubPath: ".pi/agents", interactive: true },
    { pkgSubPath: ".pi/skills", targetSubPath: ".pi/skills", interactive: true },
    {
      pkgSubPath: ".pi/extensions/subagent",
      targetSubPath: ".pi/extensions/subagent",
    },
    {
      pkgSubPath: ".pi/extensions/wikilink-lint",
      targetSubPath: ".pi/extensions/wikilink-lint",
    },
    { pkgSubPath: "docs", targetSubPath: "docs", interactive: true },
  ];
  if (newChannels.codegraph) {
    includes.push({
      pkgSubPath: ".pi/extensions/codegraph",
      targetSubPath: ".pi/extensions/codegraph",
    });
  }
  if (newChannels.entire) {
    includes.push({
      pkgSubPath: ".pi/extensions/entire",
      targetSubPath: ".pi/extensions/entire",
    });
  }

  // 5. Compute the diff plan.
  const plan = await diffTree(target, includes);

  if (versionDiff.versionChanged) {
    logger.info(`assets version: ${state.version} → ${assetsVersion}`);
  }
  if (versionDiff.cliVersionChanged) {
    logger.info(`CLI version: ${state.cliVersion} → ${cliVersion}`);
  }
  if (versionDiff.newChannels.length > 0) {
    logger.info(`new channels: ${versionDiff.newChannels.join(", ")}`);
  }
  if (versionDiff.removedChannels.length > 0) {
    logger.info(`removed channels: ${versionDiff.removedChannels.join(", ")}`);
  }

  // 6. Dry-run: print the plan and stop before any writes. We still run
  //    `resolveUpgradeActions` here (in non-interactive mode) so the user
  //    sees a decision preview alongside the raw plan — counts of how many
  //    files would be adopted, kept, removed, and backed up under the
  //    active flags. `resolveUpgradeActions` is pure (no FS or editor side
  //    effects) so this is safe in dry-run. When the plan is empty we skip
  //    the decision layer entirely; there is nothing to summarise.
  if (dryRun) {
    const planIsEmpty =
      plan.modified.length === 0 && plan.added.length === 0 && plan.removed.length === 0;
    if (!planIsEmpty) {
      // Force non-interactive: no prompts will fire, the all-adopt default
      // applies, and we never call createBackup from this path.
      const dryRunDecision = await resolveUpgradeActions(
        {
          plan,
          includes,
          target,
          prune: options.prune === true,
          interactive: false,
          interactiveSetByUser: true,
          isInteractiveEnv: false,
          yes: true,
        },
        options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
      );
      const adoptCount = dryRunDecision.adopt.size;
      const keepCount = dryRunDecision.keep.size;
      const editCount = dryRunDecision.editResults.length;
      const backupCount = dryRunDecision.backup.size;
      const removeCount = dryRunDecision.remove.size;
      logger.info(
        `Would adopt: ${adoptCount} / keep: ${keepCount} / edit: ${editCount} / backup: ${backupCount} / remove: ${removeCount}`,
      );
    }
    printPlan(plan, options.prune === true);
    logger.info("DRY RUN — no changes made");
    return;
  }

  // 7. Run the decision layer. Interactive mode requires BOTH:
  //    a. The caller didn't pass `--no-interactive` or `--yes`.
  //    b. The host has a real tty (and is not CI / PISQUAD_NO_TTY).
  //
  //    Without both, we silently fall through to the all-adopt default —
  //    preserving the legacy "no tty → batch overwrite" behaviour. The
  //    decision layer is wrapped in its own try/catch so that a Ctrl-C
  //    inside @inquirer/prompts (an ExitPromptError) leaves the target
  //    untouched and exits with code 1.
  const isInteractiveEnv =
    options.yes !== true &&
    options.interactive !== false &&
    (options.forceInteractiveEnv === true || isInteractive());
  // Heads-up: the user explicitly asked for `--interactive` but we have no
  // tty (or they used `--yes`). Without this warning the command would
  // silently downgrade to batch adopt, which is surprising for someone
  // who reached for the flag. Skip the warning when forceInteractiveEnv
  // is in play (test seam) so CI-driven suites don't see noise.
  if (
    options.forceInteractiveEnv !== true &&
    options.interactiveSetByUser === true &&
    options.interactive === true &&
    !isInteractiveEnv
  ) {
    logger.warn(
      "--interactive ignored: no TTY detected, falling back to non-interactive (adopt-new) mode",
    );
  }
  let decision: ResolvedPlan;
  try {
    decision = await resolveUpgradeActions(
      {
        plan,
        includes,
        target,
        prune: options.prune === true,
        // Must stay `=== true`: an absent flag (`undefined`) must reach the
        // decision layer as `false` so shouldPrompt's interactiveSetByUser
        // guard distinguishes "absent" from explicit `--no-interactive`.
        interactive: options.interactive === true,
        interactiveSetByUser: options.interactiveSetByUser === true,
        isInteractiveEnv,
        yes: options.yes === true,
      },
      options.decisionDeps ?? buildDefaultDecisionDeps(target, resolveAsset("")),
    );
  } catch (error) {
    // Distinguish two failure modes: a user-initiated cancellation (Ctrl-C
    // → @inquirer/core's ExitPromptError) is not a fault; surface it
    // honestly. Anything else is a real exception in the decision layer
    // (e.g. diff CLI failure, editor crash, FS error) — call it a failure
    // so the user can debug. Both still leave the target untouched
    // because the decision layer runs before the backup stage.
    const isUserCancel =
      error instanceof ExitPromptError ||
      (error instanceof Error && error.name === "ExitPromptError");
    if (isUserCancel) {
      logger.error("user cancelled — no changes made, no backup created");
    } else {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`upgrade failed during decision: ${message}`);
    }
    process.exitCode = 1;
    return;
  }

  // 8. Back up files the decision layer flagged. Both `adopt` (existing files
  //    that will be overwritten) and `edit` (existing files we will overwrite
  //    post-merge) entries get archived so the user can always recover. We
  //    emit one tarball labelled "before-upgrade" — matching the legacy
  //    command's contract so existing restore tooling keeps working.
  //
  //    Wrapped in try/catch so a missing `tar` binary, full disk, or name
  //    collision produces a clean exit-1 instead of an unhandled rejection.
  //    On backup failure we must not proceed to the copy stage (the user
  //    has no recovery path otherwise) and the target is left untouched.
  const backupSet = decision.backup;
  let backupTarPath: string | null = null;
  if (backupSet.size > 0) {
    try {
      const backupResult = await createBackup(
        target,
        Array.from(backupSet).map((relPath) => ({ relPath })),
        "before-upgrade",
      );
      backupTarPath = backupResult.path;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      logger.error(`backup failed: ${message}`);
      logger.error(
        `no changes were made to ${target}; re-run once the issue is resolved`,
      );
      process.exitCode = 1;
      return;
    }
  }

  // 9-12. Apply changes, prune, run channel-specific work. Wrapped so any
  //       failure is surfaced cleanly with exit code 1 and the backup tarball
  //       left on disk for the user to inspect / restore manually.
  try {
    // 9. Apply modified + added by syncing each include subtree from assets.
    //    copyDir overwrites only files present in src, leaving extra files in
    //    dest alone — so user-added files survive unless --prune handles them
    //    explicitly below.
    //
    //    The filter combines three concerns:
    //    - codegraph subtree skips node_modules and package-lock.json (would
    //      be restored by `npm install` anyway and copying is slow).
    //    - The decision layer's `keep` set is skipped so user-modified
    //      interactive files are NOT overwritten by the recursive copy.
    //    - Files handled by `editResults` are skipped here because step 10
    //      writes the user-merged content over the top of whatever the copy
    //      would have produced.
    for (const inc of includes) {
      const source = resolveAsset(inc.pkgSubPath);
      const destination = join(target, inc.targetSubPath);
      const isCodegraph = inc.pkgSubPath === ".pi/extensions/codegraph";
      copyDir(source, destination, {
        filter: (_abs, rel) => {
          const targetRel = inc.targetSubPath ? `${inc.targetSubPath}/${rel}` : rel;
          if (isCodegraph && (rel === "node_modules" || rel === "package-lock.json")) return false;
          if (decision.keep.has(targetRel)) return false;
          if (decision.editResults.some((e) => e.relPath === targetRel)) return false;
          return true;
        },
        onSkip: (rel, reason) => logger.warn(`Skipped ${rel} (${reason})`),
      });
    }

    // 10. Write back user-edited files. The recursive copy in step 9 staged
    //     the new assets version; we overwrite with the user's edited
    //     content here. Atomic write so a crash mid-write cannot corrupt
    //     the file. `matchesTheirs === true` means the user opened the
    //     editor, saw the new content, and saved it verbatim — i.e. they
    //     effectively chose "Adopt new" via the editor.
    for (const ed of decision.editResults) {
      const abs = join(target, ed.relPath);
      ensureDir(dirname(abs));
      atomicWriteFile(abs, ed.content);
      logger.info(
        `wrote edited ${ed.relPath}${ed.matchesTheirs ? " (matches new version — merged)" : " (user edit kept)"}`,
      );
    }

    // 11. Handle removed files: walk the decision's `remove` set (which only
    //     contains user-confirmed deletions when --prune is in play).
    for (const relPath of decision.remove) {
      const abs = join(target, relPath);
      try {
        rmSync(abs, { force: true });
      } catch (error) {
        logger.warn(
          `Failed to prune ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    }

    // 12. Channel-specific handling. codegraph npm install runs only when
    //     the extension payload actually changed AND we adopted/edited
    //     something under .pi/extensions/codegraph/. We consult the
    //     decision layer's sets (not the raw plan) so a "keep my codegraph
    //     override" choice does not trigger a npm install that would clobber
    //     the kept file via package.json's deps update.
    const codegraphNewlyEnabled = newChannels.codegraph && !state.channels.codegraph;
    const entireNewlyEnabled = newChannels.entire && !state.channels.entire;

    if (codegraphNewlyEnabled) {
      // installCodegraph does its own copy + npm install + codegraph init.
      // The copy we did in step 9 is redundant but harmless (writes the same
      // content) — we let installCodegraph own the full bootstrap.
      await installCodegraph(target, { logger });
    } else if (newChannels.codegraph) {
      const codegraphTouched =
        Array.from(decision.adopt).some((p) =>
          p.startsWith(".pi/extensions/codegraph/"),
        ) ||
        decision.editResults.some((e) => e.relPath.startsWith(".pi/extensions/codegraph/"));
      if (codegraphTouched) {
        await runNpmInstall(join(target, ".pi", "extensions", "codegraph"));
      }
    }

    if (entireNewlyEnabled) {
      await installEntire(target, { logger });
    }

    // 13. codegraph.json: only copy when the target lacks one. We never
    //     overwrite the user's existing config (respect their customisation).
    //     When codegraph is newly enabled, installCodegraph already handles
    //     this; we only need to run the check for the pre-existing case.
    if (newChannels.codegraph && !codegraphNewlyEnabled) {
      const configDest = join(target, "codegraph.json");
      if (!existsSync(configDest)) {
        const configSource = resolveAsset("codegraph.json");
        if (existsSync(configSource)) {
          copyFileSync(configSource, configDest);
          logger.info(`copied codegraph.json → ${configDest}`);
        }
      } else {
        logger.info("codegraph.json already present, keeping user copy");
      }
    }
  } catch (error) {
    logger.error(`upgrade failed: ${error instanceof Error ? error.message : String(error)}`);
    if (backupSet.size > 0) {
      logger.error(`backup retained on disk under .pi/.pisquad/backups/ for manual restore`);
    }
    process.exitCode = 1;
    return;
  }

  // 14. Persist new state. We always write the latest assets version —
  //     even when the user chose "keep my version" for some files, so
  //     the package-side baseline is still current. Per-user overrides
  //     reappear in the next diff because their hashes differ from the
  //     assets' hashes; the warning at the end reminds the user of that.
  writeState(target, {
    version: assetsVersion,
    cliVersion,
    channels: newChannels,
    lastUpgradedAt: new Date().toISOString(),
  });

  // 15. Summary.
  const keptInteractive = Array.from(decision.entries.values()).filter(
    (d) => d === "keep",
  ).length;
  printSummary({
    newChannels,
    backupCount: backupSet.size,
    backupPaths: backupTarPath === null ? [] : [backupTarPath],
    removedCount: decision.remove.size,
    pruned: options.prune === true,
    statePath: stateFile(target),
    modifiedCount: plan.modified.length,
    addedCount: plan.added.length,
    adoptedCount: decision.adopt.size,
    keptCount: keptInteractive,
    editedCount: decision.editResults.length,
  });
  if (keptInteractive > 0) {
    logger.warn(
      `kept ${keptInteractive} user modification(s) — they will reappear in next upgrade's diff`,
    );
  }
}

async function runNpmInstall(cwd: string): Promise<void> {
  try {
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: EXEC_MAX_BUFFER,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`npm install in ${cwd} failed: ${message}`);
  }
}

function printPlan(plan: DiffPlan, prune: boolean): void {
  logger.info(`modified (${plan.modified.length}):`);
  for (const m of plan.modified) logger.info(`  M ${m.relPath}`);
  logger.info(`added (${plan.added.length}):`);
  for (const a of plan.added) logger.info(`  A ${a.relPath}`);
  logger.info(`removed (${plan.removed.length}):`);
  for (const r of plan.removed) logger.info(`  D ${r.relPath}${prune ? " (will delete)" : " (will keep)"}`);
  logger.info(`unchanged (${plan.unchanged.length})`);
  if (prune && plan.removed.length > 0) {
    logger.info(`Pruning will also back up the ${plan.removed.length} removed file(s) before deletion.`);
  }
}

interface Summary {
  newChannels: Channels;
  backupCount: number;
  backupPaths: string[];
  removedCount: number;
  pruned: boolean;
  statePath: string;
  modifiedCount: number;
  addedCount: number;
  /** Number of files whose content was adopted from assets this run. */
  adoptedCount: number;
  /** Number of files the user explicitly chose to keep (interactive + --prune-deleted kept). */
  keptCount: number;
  /** Number of files the user edited in $EDITOR and wrote back. */
  editedCount: number;
}

function printSummary(s: Summary): void {
  const parts = ["core"];
  if (s.newChannels.codegraph) parts.push("codegraph");
  if (s.newChannels.entire) parts.push("entire");
  logger.info(`Channels: ${parts.join(" + ")}`);
  logger.info(`Modified: ${s.modifiedCount}, added: ${s.addedCount}`);
  logger.info(`Adopted: ${s.adoptedCount}, kept: ${s.keptCount}, edited: ${s.editedCount}`);
  if (s.removedCount > 0) {
    if (s.pruned) {
      logger.info(`Removed: ${s.removedCount} (pruned)`);
    } else {
      logger.info(`Removed: ${s.removedCount} (kept — pass --prune to delete)`);
    }
  }
  if (s.backupCount > 0) {
    logger.info(`Backup: ${s.backupCount} file(s) archived`);
    for (const p of s.backupPaths) logger.info(`  ${p}`);
  }
  logger.info(`State: ${s.statePath}`);
  logger.success("upgrade complete");
}

// ---- channel merging ---------------------------------------------------------

function parseChannelList(input: string | undefined): Set<Exclude<ChannelKey, "core">> {
  const out = new Set<Exclude<ChannelKey, "core">>();
  if (!input) return out;
  for (const raw of input.split(",")) {
    const v = raw.trim().toLowerCase();
    if (!v) continue;
    if (v === "codegraph" || v === "entire") out.add(v);
    else if (v !== "core") throw new Error(`Unknown channel: ${v}`);
  }
  return out;
}

/**
 * Merge `--with` / `--without` flags onto the state's existing channel set.
 *
 *   - state.channels is the baseline (no implicit changes).
 *   - `--with X` adds X to the baseline (idempotent).
 *   - `--without X` removes X from the baseline (idempotent).
 *   - `--with` and `--without` are mutually exclusive.
 *
 * `core` is always `true`; the schema pins it. The task spec uses this same
 * merge order so a later `pisquad upgrade --with codegraph` after a core-only
 * install adds the channel without re-prompting.
 */
function mergeChannels(base: Channels, options: { with?: string; without?: string }): Channels {
  const withSet = parseChannelList(options.with);
  const withoutSet = parseChannelList(options.without);
  if (withSet.size > 0 && withoutSet.size > 0) {
    throw new Error("Cannot combine --with and --without");
  }
  const next: Channels = {
    core: true,
    codegraph: base.codegraph,
    entire: base.entire,
  };
  if (withSet.size > 0) {
    for (const k of withSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = true;
  }
  if (withoutSet.size > 0) {
    for (const k of withoutSet) (next as unknown as Record<Exclude<ChannelKey, "core">, boolean>)[k] = false;
  }
  return next;
}

import { checkbox } from "@inquirer/prompts";
import { isInteractive } from "./env.js";

export type OptionalChannel = "codegraph" | "entire";

export interface Channels {
  core: true;
  codegraph: boolean;
  entire: boolean;
}

export interface ChannelDecisionOptions {
  all?: boolean;
  with?: string | string[];
  without?: string | string[];
  yes?: boolean;
  env?: NodeJS.ProcessEnv;
  target?: string;
}

const coreOnly: Channels = { core: true, codegraph: false, entire: false };

/** Ask only about optional channels; core is deliberately always selected. */
export async function promptChannels(_target?: string): Promise<Channels> {
  const selected = await checkbox<OptionalChannel>({
    message: "Select optional pi-squad channels",
    choices: [
      { name: "codegraph", value: "codegraph" },
      { name: "entire", value: "entire" },
    ],
  });

  return {
    core: true,
    codegraph: selected.includes("codegraph"),
    entire: selected.includes("entire"),
  };
}

function values(input: string | string[] | undefined): string[] {
  if (input === undefined) return [];
  const parts = Array.isArray(input) ? input : input.split(",");
  return parts.map((part) => part.trim().toLowerCase()).filter(Boolean);
}

function optionalChannels(input: string | string[] | undefined): Set<OptionalChannel> {
  const result = new Set<OptionalChannel>();
  for (const value of values(input)) {
    if (value === "codegraph" || value === "entire") result.add(value);
    else if (value !== "core") throw new Error(`Unknown channel: ${value}`);
  }
  return result;
}

function withChannels(channels: Set<OptionalChannel>): Channels {
  return {
    core: true,
    codegraph: channels.has("codegraph"),
    entire: channels.has("entire"),
  };
}

/**
 * Decide channels in the documented non-interactive precedence order.
 * Explicit flags win over environment variables; no tty always falls back to core.
 */
export async function decideChannels(opts: ChannelDecisionOptions = {}): Promise<Channels> {
  if (opts.all) return { core: true, codegraph: true, entire: true };

  const explicitWith = values(opts.with);
  const explicitWithout = values(opts.without);
  if (explicitWith.length > 0 && explicitWithout.length > 0) {
    throw new Error("Cannot combine --with and --without");
  }

  if (explicitWith.length > 0) {
    return withChannels(optionalChannels(explicitWith));
  }

  if (explicitWithout.length > 0) {
    const exclude = optionalChannels(explicitWithout);
    return {
      core: true,
      codegraph: !exclude.has("codegraph"),
      entire: !exclude.has("entire"),
    };
  }

  if (opts.yes) return { ...coreOnly };

  const env = opts.env ?? process.env;
  const environmentWith = values(env.PISQUAD_WITH);
  const environmentWithout = values(env.PISQUAD_WITHOUT);
  if (environmentWith.length > 0 && environmentWithout.length > 0) {
    throw new Error("Cannot combine PISQUAD_WITH and PISQUAD_WITHOUT");
  }

  if (environmentWith.length > 0) {
    return withChannels(optionalChannels(environmentWith));
  }

  if (environmentWithout.length > 0) {
    const exclude = optionalChannels(environmentWithout);
    return {
      core: true,
      codegraph: !exclude.has("codegraph"),
      entire: !exclude.has("entire"),
    };
  }

  if (isInteractive()) return promptChannels(opts.target);
  return { ...coreOnly };
}

import pc from "picocolors";

let verbose = false;

export const logger = {
  setVerbose(value: boolean): void {
    verbose = value;
  },
  info(message: string): void {
    console.log(pc.cyan(message));
  },
  warn(message: string): void {
    console.warn(pc.yellow(message));
  },
  error(message: string): void {
    console.error(pc.red(message));
  },
  success(message: string): void {
    console.log(pc.green(message));
  },
  step(message: string): void {
    if (verbose) console.log(pc.dim(message));
  },
};

export const setVerbose = (value: boolean): void => logger.setVerbose(value);
export const info = (message: string): void => logger.info(message);
export const warn = (message: string): void => logger.warn(message);
export const error = (message: string): void => logger.error(message);
export const success = (message: string): void => logger.success(message);
export const step = (message: string): void => logger.step(message);

import { createHash } from "node:crypto";
import type { DiffPlan, PkgInclude } from "../lib/diff.js";
import { logger } from "../lib/logger.js";

/**
 * Pure coordination layer for `pisquad upgrade`.
 *
 * `resolveUpgradeActions` decides, for every entry in the `DiffPlan`,
 * whether the file should be:
 *
 *   - `adopt`        → copied from assets into the target (with backup first
 *                      for `modified`/`removed` that already exist on disk).
 *   - `keep`         → left untouched on disk. Used both for user-chosen
 *                      "keep my edits" picks and for `removed` entries when
 *                      `--prune` is not in play.
 *   - `edit`         → user opened `$EDITOR`, merged manually; the resulting
 *                      content is written back after copy and the file is
 *                      backed up (it contains the user's pre-edit version).
 *
 * The function is intentionally free of `inquirer` / `fs` / `child_process`
 * calls so it is unit-testable with fake `DecisionDeps`. The default
 * implementation lives in `decision-defaults.ts` and wires up the real
 * prompts + `diff` / editor.
 */

/** Kind of change the package is making to a file in the target. */
export type FileKind = "modified" | "added" | "removed";

/** User-confirmed outcome for a single file. */
export type FileDecision = "adopt" | "keep" | "edit";

/** Top-level strategy picked by the user before per-file decisions begin. */
export type StrategyMode = "all-adopt" | "all-keep" | "per-file";

/** A single entry in the plan, augmented with the include's interactive flag. */
export interface PlanEntry {
  relPath: string;
  kind: FileKind;
  fromHash?: string;
  toHash?: string;
  /** True when the include owning this file is user-editable territory. */
  interactive: boolean;
}

/** Result of a per-file `edit` decision. */
export interface EditResult {
  relPath: string;
  content: string;
  /**
   * True when the user saved content whose hex digest equals the new assets
   * version's hash. Surfaced in the upgrade summary so the user can see that
   * their edit collapsed back to "adopt new".
   */
  matchesTheirs: boolean;
}

/**
 * The aggregated output of the decision layer. Consumed by the upgrade
 * command to drive backup, copy, prune, edit-write-back, and summary.
 *
 * Sets partition the plan's file paths by intent:
 *
 *   - `entries`   — per-interactive-file decision map (excludes managed files).
 *   - `adopt`     — files whose content should be copied from assets (the
 *                   union of "managed modified/added" and "interactive adopt"
 *                   decisions, minus files handled by `editResults`).
 *   - `keep`      — files to leave alone. The copy filter MUST skip these
 *                   so the user's local copy survives.
 *   - `remove`    — files to delete (only populated when `--prune` is set and
 *                   the user confirmed the deletion).
 *   - `backup`    — files that must be archived before any write or delete.
 *                   Includes all `modified` + `removed` that exist on disk,
 *                   plus every `edit` file (whose tar contains the user's
 *                   pre-edit version).
 *   - `editResults` — write-back list, processed after copy so the staged
 *                   copy is overwritten with the user-edited content.
 */
export interface ResolvedPlan {
  entries: Map<string, FileDecision>;
  adopt: Set<string>;
  keep: Set<string>;
  remove: Set<string>;
  backup: Set<string>;
  editResults: EditResult[];
  mode: StrategyMode;
}

/** Inputs the caller must supply to drive a decision. */
export interface DecisionInput {
  plan: DiffPlan;
  includes: PkgInclude[];
  /**
   * The install target root. Required so the default adapter can read
   * `current` content for `edit` decisions. Decision.ts itself never reads
   * files; this field is forwarded to the adapter via `deps`.
   */
  target: string;
  prune: boolean;
  /**
   * Narrowed form of the raw `--interactive` / `--no-interactive` flag as
   * seen by the decision layer. The call site in `upgradeCommand` always
   * passes `options.interactive === true`, so the three meaningful values
   * reaching this layer are:
   *
   *   - `true`  → user passed `--interactive` (explicit opt-in).
   *   - `false` → EITHER the user passed `--no-interactive`, OR they
   *               passed no flag at all. These two cases are NOT
   *               distinguishable from this field alone; consult
   *               `interactiveSetByUser` to tell them apart. The
   *               decision logic in `shouldPrompt` does so explicitly.
   *
   * Combined with `isInteractiveEnv` and `yes` to decide whether any
   * prompt is fired.
   */
  interactive: boolean;
  /**
   * True when the user explicitly passed `--interactive` or `--no-interactive`.
   * Used so we can decide whether a non-interactive run was a deliberate
   * "I want batch behaviour" choice vs. a fallback from missing tty.
   */
  interactiveSetByUser: boolean;
  /** TTY + non-CI check from env.isInteractive(). */
  isInteractiveEnv: boolean;
  /** True when -y / --yes was passed; always suppresses prompts. */
  yes?: boolean;
}

/**
 * Test seam — every prompt, renderer, editor, env lookup, and hash function
 * is injectable. Production code calls `buildDefaultDecisionDeps()` from
 * `decision-defaults.ts`; tests pass fakes that record calls and return
 * scripted answers.
 */
export interface DecisionDeps {
  promptStrategy?: () => Promise<StrategyMode>;
  promptFileDecision?: (
    entry: PlanEntry,
    remaining: number,
    kind: FileKind,
  ) => Promise<FileDecision | "__adopt-all" | "__keep-all">;
  /**
   * Render the unified diff (or contents) for one interactive entry BEFORE
   * `promptFileDecision` is shown, so the user always sees what they're
   * about to decide on. The default adapter in `decision-defaults.ts`
   * resolves the absolute paths itself from the closures captured by
   * `buildDefaultDecisionDeps`; this layer only knows about `relPath` and
   * the file's `kind`.
   *
   *   - `modified` → unified diff from current to new.
   *   - `added`    → show the new file's full content.
   *   - `removed`  → show the file that would be deleted (or a notice).
   *
   * Optional — when not supplied (e.g. test deps that don't need the
   * preview) the diff step is silently skipped. Failures inside the
   * renderer are also swallowed (logged as a warn) so a missing-file
   * read or a system-`diff` crash never blocks the prompt path.
   */
  renderUnifiedDiff?: (relPath: string, kind: FileKind) => Promise<string>;
  /**
   * Open an editor on the user's copy of `relPath` and return the merged
   * content. The default adapter in `decision-defaults.ts` reads
   * `currentContent` from `<target>/<relPath>` and `newContent` from
   * `<assetsRoot>/<relPath>` itself; the empty-string sentinels from
   * `decision.ts` are placeholders the adapter ignores.
   */
  openEditor?: (relPath: string, currentContent: string, newContent: string) => Promise<string>;
  env?: NodeJS.ProcessEnv;
  sha256Content?: (content: string) => string;
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

/** Find the include that owns a target-relative path. */
function findInclude(includes: PkgInclude[], relPath: string): PkgInclude | undefined {
  // Match from longest targetSubPath first so ".pi/extensions/codegraph" wins
  // over ".pi" if both were ever registered. We don't currently do that, but
  // the sort makes the lookup robust against future changes.
  const sorted = [...includes].sort(
    (a, b) => b.targetSubPath.length - a.targetSubPath.length,
  );
  for (const inc of sorted) {
    if (!inc.targetSubPath) return inc;
    if (relPath === inc.targetSubPath) return inc;
    if (relPath.startsWith(`${inc.targetSubPath}/`)) return inc;
  }
  return undefined;
}

/**
 * Build the PlanEntry list from a DiffPlan + includes, flagging each entry
 * with the owning include's `interactive` setting.
 *
 * The diff's `fromHash` / `toHash` are preserved as-is so the decision layer
 * can reason about whether a file even exists on disk (removed) or in assets
 * (added).
 */
function entriesFromPlan(plan: DiffPlan, includes: PkgInclude[]): PlanEntry[] {
  const entries: PlanEntry[] = [];
  for (const m of plan.modified) {
    const inc = findInclude(includes, m.relPath);
    entries.push({
      relPath: m.relPath,
      kind: "modified",
      fromHash: m.fromHash,
      toHash: m.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const a of plan.added) {
    const inc = findInclude(includes, a.relPath);
    entries.push({
      relPath: a.relPath,
      kind: "added",
      toHash: a.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const r of plan.removed) {
    const inc = findInclude(includes, r.relPath);
    entries.push({
      relPath: r.relPath,
      kind: "removed",
      fromHash: r.fromHash,
      interactive: inc?.interactive === true,
    });
  }
  // Keep the same order plan.modified/added/removed are sorted in (by relPath
  // alphabetically within each bucket) so per-file prompts are deterministic.
  return entries;
}

/**
 * Decide whether we should prompt the user at all. Three independent
 * suppressors short-circuit to the "no prompts → all-adopt" default:
 *
 *   1. `yes === true` (`--yes`).
 *   2. `interactiveSetByUser === true && interactive === false` (explicit
 *      `--no-interactive`).
 *   3. `isInteractiveEnv === false` (no tty / CI / PISQUAD_NO_TTY).
 *
 * When `interactiveSetByUser === false`, the caller-narrowed
 * `interactive === false` means the flag was absent, not that the user opted
 * out. If a tty is available, that combination proceeds to the interactive
 * flow; this is the implicit-interactive path required by ADR-0003 §5.
 */
function shouldPrompt(input: DecisionInput): boolean {
  if (input.yes === true) return false;
  // Only an EXPLICIT `--no-interactive` is treated as opt-out. When
  // the user did not pass the flag, `interactive` arrives as `false`
  // (the caller narrows via `options.interactive === true`); in that
  // case we must still consult `isInteractiveEnv` so a real tty
  // triggers the interactive flow per ADR-0003 §5.
  if (input.interactiveSetByUser && input.interactive === false) return false;
  return input.isInteractiveEnv;
}

/**
 * Compute the upgrade's action plan.
 *
 * The function is intentionally free of side effects beyond the supplied
 * `deps`. It does NOT read files, spawn editors, or write anything. Real I/O
 * is funnelled through `deps` so tests can drive every branch deterministically.
 */
export async function resolveUpgradeActions(
  input: DecisionInput,
  deps: DecisionDeps = {},
): Promise<ResolvedPlan> {
  const sha256Content = deps.sha256Content ?? defaultSha256Content;

  const empty: ResolvedPlan = {
    entries: new Map(),
    adopt: new Set(),
    keep: new Set(),
    remove: new Set(),
    backup: new Set(),
    editResults: [],
    mode: "all-adopt",
  };

  const allEntries = entriesFromPlan(input.plan, input.includes);
  if (allEntries.length === 0) return empty;

  const interactiveEntries = allEntries.filter((e) => e.interactive);
  const managedEntries = allEntries.filter((e) => !e.interactive);

  // 1. Managed (non-interactive) entries follow the legacy behaviour: modified
  //    overwrites (the legacy code path also backs them up), added copies, and
  //    removed is kept unless --prune is in play. None of these depend on the
  //    user-facing prompts, so we resolve them up front.
  for (const entry of managedEntries) {
    switch (entry.kind) {
      case "modified":
        empty.adopt.add(entry.relPath);
        empty.backup.add(entry.relPath);
        break;
      case "added":
        empty.adopt.add(entry.relPath);
        break;
      case "removed":
        if (input.prune) {
          empty.remove.add(entry.relPath);
          empty.backup.add(entry.relPath);
        } else {
          empty.keep.add(entry.relPath);
        }
        break;
    }
  }

  // 2. If there are no interactive entries, we're done. This is the common
  //    case for projects that only have extension-channel updates, and it
  //    keeps the upgrade behaviour identical to the pre-interactive version.
  if (interactiveEntries.length === 0) return empty;

  // 3. Decide the strategy. When we cannot prompt, default to all-adopt — that
  //    matches the legacy "no-tty → batch overwrite" behaviour and is also the
  //    command's documented non-interactive fallback.
  let mode: StrategyMode;
  if (!shouldPrompt(input)) {
    mode = "all-adopt";
  } else if (deps.promptStrategy === undefined) {
    // Should not happen in practice (the default deps always supply it), but
    // guard so the function is safe to call with `deps = {}`.
    mode = "all-adopt";
  } else {
    mode = await deps.promptStrategy();
  }
  empty.mode = mode;

  // 4. Apply the strategy to interactive entries.
  if (mode === "all-adopt") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          // With --prune, "all-adopt" means "delete the file". The user's
          // intent is clear: they accepted the upgrade plan and want every
          // stale file gone. Without --prune we keep the file — the legacy
          // behaviour for "no prune" survives.
          if (input.prune) {
            empty.entries.set(entry.relPath, "adopt");
            empty.remove.add(entry.relPath);
            empty.backup.add(entry.relPath);
          } else {
            empty.entries.set(entry.relPath, "keep");
            empty.keep.add(entry.relPath);
          }
          break;
      }
    }
    return empty;
  }

  if (mode === "all-keep") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
        case "added":
        case "removed":
          empty.entries.set(entry.relPath, "keep");
          empty.keep.add(entry.relPath);
          break;
      }
    }
    return empty;
  }

  // 5. per-file: walk the entries in deterministic order, ask the user, and
  //    honour batch shortcuts that fan out to remaining entries.
  if (deps.promptFileDecision === undefined || deps.openEditor === undefined) {
    // Same fallback as above — if the caller asked for per-file but didn't
    // wire the prompt functions, we degrade to all-adopt rather than throw.
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          if (input.prune) {
            empty.entries.set(entry.relPath, "adopt");
            empty.remove.add(entry.relPath);
            empty.backup.add(entry.relPath);
          } else {
            empty.entries.set(entry.relPath, "keep");
            empty.keep.add(entry.relPath);
          }
          break;
      }
    }
    return empty;
  }

  // Walk the interactive entries; track remaining = how many entries the user
  // has not yet seen, so batch shortcuts can advertise "Adopt all remaining
  // (N)". Index-based loop because we break out via the batch shortcuts.
  for (let i = 0; i < interactiveEntries.length; i++) {
    const entry = interactiveEntries[i]!;
    const remaining = interactiveEntries.length - i - 1;
    // `removed` entries without --prune cannot actually be deleted, so
    // prompting the user about a Delete/Keep choice would only produce
    // confusing no-ops. Auto-apply keep (matching the strategy-default and
    // managed-entry paths) and skip the prompt (and its diff preview)
    // entirely.
    if (entry.kind === "removed" && !input.prune) {
      empty.entries.set(entry.relPath, "keep");
      empty.keep.add(entry.relPath);
      continue;
    }
    // Render the file's diff / preview BEFORE firing the prompt, so the
    // user is never asked to choose blindly. Best-effort: if the dep is
    // missing (common in tests) we skip; if it throws we warn and fall
    // through to the prompt so the upgrade flow is never blocked.
    if (deps.renderUnifiedDiff !== undefined) {
      try {
        await deps.renderUnifiedDiff(entry.relPath, entry.kind);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        logger.warn(
          `could not render diff for ${entry.relPath}: ${message} — skipping preview, proceeding to prompt`,
        );
      }
    }
    const answer = await deps.promptFileDecision(entry, remaining, entry.kind);
    if (answer === "__adopt-all" || answer === "__keep-all") {
      // Resolve the current entry with the batch decision, then fill the rest.
      const decision: FileDecision = answer === "__adopt-all" ? "adopt" : "keep";
      await applyInteractiveDecision(empty, entry, decision, deps, sha256Content, input.prune);
      for (let j = i + 1; j < interactiveEntries.length; j++) {
        await applyInteractiveDecision(
          empty,
          interactiveEntries[j]!,
          decision,
          deps,
          sha256Content,
          input.prune,
        );
      }
      return empty;
    }
    await applyInteractiveDecision(empty, entry, answer, deps, sha256Content, input.prune);
  }
  return empty;
}

/** Apply a single per-file decision to the in-progress plan. */
async function applyInteractiveDecision(
  plan: ResolvedPlan,
  entry: PlanEntry,
  decision: FileDecision,
  deps: DecisionDeps,
  sha256Content: (content: string) => string,
  prune: boolean,
): Promise<void> {
  plan.entries.set(entry.relPath, decision);
  if (decision === "keep") {
    plan.keep.add(entry.relPath);
    return;
  }
  if (decision === "adopt") {
    if (entry.kind === "removed") {
      // "adopt" for a removed file = "delete this file". Only honourable
      // when --prune is in play; otherwise we silently keep the user's copy
      // (the prompt defaults "Adopt" for removed entries to mean "delete",
      // so the user expects this behaviour even though their pick is
      // effectively no-op'd without --prune).
      if (prune) {
        plan.remove.add(entry.relPath);
        plan.backup.add(entry.relPath);
      } else {
        plan.keep.add(entry.relPath);
      }
      return;
    }
    plan.adopt.add(entry.relPath);
    if (entry.kind === "modified") {
      plan.backup.add(entry.relPath);
    }
    return;
  }
  // decision === "edit": invoke the editor via deps. openEditor is guaranteed
  // to exist here because the caller only enters per-file mode when it does.
  // (resolveUpgradeActions short-circuits to all-adopt otherwise.)
  const openEditor = deps.openEditor!;
  // currentContent / newContent are filled by the default adapter; tests can
  // supply a stub that ignores them and returns a canned string.
  const edited = await openEditor(entry.relPath, "", "");
  if (edited.length === 0) {
    // Empty editor result → treat as "keep my version". Surface this via
    // entries map (already set) and skip backup; the file is left alone.
    plan.keep.add(entry.relPath);
    return;
  }
  const matchesTheirs = typeof entry.toHash === "string" && sha256Content(edited) === entry.toHash;
  plan.editResults.push({ relPath: entry.relPath, content: edited, matchesTheirs });
  plan.backup.add(entry.relPath);
}

import { spawn } from "node:child_process";
import { logger as defaultLogger } from "../lib/logger.js";
import { execCapture as defaultExecCapture, which as defaultWhich, type ExecCaptureResult } from "../lib/env.js";
import { readCliVersion } from "../lib/version.js";
import type { Logger } from "../lib/plugins/types.js";

/**
 * CLI self-update stage of `pisquad upgrade`.
 *
 * The contract is:
 *
 *   - Honor `--no-self` (CLI flag) or `PISQUAD_NO_SELF=1` (env): when set,
 *     skip the entire stage and report `updated: false`.
 *   - Only attempt an update when the `pisquad` binary on PATH resolves to a
 *     file under npm's global prefix (i.e. was installed via `npm i -g`). When
 *     the binary is missing, or is a non-global install (e.g. `npx @nicklin/pisquad@latest`
 *     sandbox or local dev tree), print "CLI not from global npm, skipping
 *     self-update" and return.
 *   - When the install is confirmed global, compare the version embedded in
 *     this CLI's `package.json` against the latest version on the npm
 *     registry. Skip the reinstall (return `updated: false`, reason
 *     `"already latest"`) when they match — this prevents the
 *     `upgrade → re-run → upgrade` loop that an unconditional
 *     `npm install -g @nicklin/pisquad@latest` would create, since npm
 *     considers itself successful even when there is nothing to install.
 *   - When the registry version differs, run `npm install -g
 *     @nicklin/pisquad@latest` and, on success, return `updated: true` so the
 *     upgrade command can prompt the user to re-run with the new binary.
 *   - When the registry call itself fails (offline, non-zero exit), skip the
 *     self-update with a warning and return `updated: false`, reason
 *     `"npm view failed"` — we deliberately do not reinstall on an unknown
 *     remote state.
 *   - On `npm install -g` failure, throw — the upgrade command aborts
 *     without touching the target project.
 *
 * The `deps` hook is for tests only: callers should not pass it in production.
 */

export interface SelfUpdateDeps {
  which?: (cmd: string) => string | null;
  execCapture?: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>;
  /**
   * Override the actual `npm install -g` runner. The default spawns npm with
   * a 2-minute timeout; tests inject a stub that returns a synthetic
   * ExecCaptureResult so no real npm process is ever spawned.
   */
  runNpmInstallGlobal?: () => Promise<ExecCaptureResult>;
}

export interface SelfUpdateOptions {
  logger?: Logger;
  /** Honor the CLI's `--no-self` flag. */
  noSelf?: boolean;
  /** @internal Test seam — override `which` / `execCapture`. */
  deps?: SelfUpdateDeps;
}

export interface SelfUpdateResult {
  updated: boolean;
  /** Human-readable reason for the skip / failure (diagnostic only). */
  reason?: string;
}

const NPM_TIMEOUT_MS = 2 * 60 * 1000; // 2 minutes — global installs are usually fast
const NPM_GLOBAL_ARGS = ["install", "-g", "@nicklin/pisquad@latest", "--no-audit", "--no-fund"];

/**
 * Spawn `npm install -g @nicklin/pisquad@latest` with a hard timeout.
 *
 * `execCapture` in env.ts does not enforce a timeout, and a stuck global
 * install would otherwise block the whole upgrade command. We use a dedicated
 * spawn here so the timeout is scoped to this stage only.
 */
function runNpmInstallGlobal(): Promise<ExecCaptureResult> {
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    let settled = false;

    let child: ReturnType<typeof spawn>;
    try {
      child = spawn("npm", NPM_GLOBAL_ARGS, { stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      reject(new Error(`failed to spawn npm: ${message}`));
      return;
    }

    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill("SIGTERM");
      reject(new Error(`npm install -g @nicklin/pisquad@latest timed out after ${NPM_TIMEOUT_MS / 1000}s`));
    }, NPM_TIMEOUT_MS);

    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");
    child.stdout?.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr?.on("data", (chunk: string) => {
      stderr += chunk;
    });
    child.on("error", (error) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      reject(error);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      resolve({ stdout, stderr, exitCode: code ?? 1 });
    });
  });
}

/**
 * Ask npm for the latest published version of `@nicklin/pisquad`. Returns
 * the trimmed version string on success, or `null` when the registry call
 * failed (offline, non-zero exit, or empty stdout). The caller is expected
 * to treat a `null` result as "could not determine latest version" and skip
 * the self-update with a warning rather than risk an unconditional reinstall.
 */
async function getLatestVersion(
  execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>,
): Promise<string | null> {
  const result = await execCapture("npm", ["view", "@nicklin/pisquad", "version"]);
  if (result.exitCode !== 0) return null;
  const version = result.stdout.trim();
  return version.length > 0 ? version : null;
}

/**
 * Ask npm for the global prefix. New npm exposes `npm prefix -g`; older
 * versions answer the same question via `npm config get prefix`. We try the
 * modern form first and fall back to the legacy one so older Node
 * distributions bundled with older npm still work.
 */
async function getGlobalPrefix(
  execCapture: (cmd: string, args?: string[]) => Promise<ExecCaptureResult>,
): Promise<string | null> {
  const modern = await execCapture("npm", ["prefix", "-g"]);
  if (modern.exitCode === 0) {
    const value = modern.stdout.trim();
    if (value) return value;
  }
  const legacy = await execCapture("npm", ["config", "get", "prefix"]);
  if (legacy.exitCode === 0) {
    const value = legacy.stdout.trim();
    if (value) return value;
  }
  return null;
}

/** Strip trailing slashes and resolve the bin subdir of an npm prefix. */
function globalBinDir(prefix: string): string {
  const trimmed = prefix.replace(/\/+$/, "");
  return `${trimmed}/bin`;
}

/**
 * True when `child` is at or under `parent`. Both arguments are expected to be
 * absolute, POSIX-style paths. We refuse to match `/foo` against `/foobar`.
 */
function pathStartsWith(child: string, parent: string): boolean {
  if (child === parent) return true;
  if (!child.startsWith(parent)) return false;
  const next = child.charAt(parent.length);
  return next === "/" || next === "";
}

export async function selfUpdate(opts: SelfUpdateOptions = {}): Promise<SelfUpdateResult> {
  const logger = opts.logger ?? defaultLogger;
  const which = opts.deps?.which ?? defaultWhich;
  const execCapture = opts.deps?.execCapture ?? defaultExecCapture;

  if (opts.noSelf === true || process.env.PISQUAD_NO_SELF === "1") {
    return { updated: false, reason: "--no-self or PISQUAD_NO_SELF=1" };
  }

  const currentPath = which("pisquad");
  if (!currentPath) {
    logger.info("CLI not on PATH, skipping self-update");
    return { updated: false, reason: "pisquad not on PATH" };
  }

  const globalPrefix = await getGlobalPrefix(execCapture);
  if (!globalPrefix) {
    logger.warn("Unable to determine npm global prefix, skipping self-update");
    return { updated: false, reason: "npm prefix detection failed" };
  }

  const binDir = globalBinDir(globalPrefix);
  if (!pathStartsWith(currentPath, binDir)) {
    logger.info("CLI not from global npm, skipping self-update");
    return { updated: false, reason: `not under npm global bin (${binDir})` };
  }

  // Confirmed global install — but only re-run `npm install -g` when the
  // registry actually has a newer version. An unconditional reinstall always
  // exits 0 (npm considers itself "up to date"), which previously made
  // `selfUpdate` return `updated: true` on every run and forced the user
  // into a `pisquad upgrade → re-run → upgrade → re-run` loop. We compare
  // the installed version (from this CLI's package.json) to the registry
  // version (`npm view`) and short-circuit when they match.
  const currentVersion = readCliVersion();
  const latestVersion = await getLatestVersion(execCapture);
  if (latestVersion === null) {
    logger.warn("Could not check latest pisquad version on registry, skipping self-update");
    return { updated: false, reason: "npm view failed" };
  }
  if (latestVersion === currentVersion) {
    logger.info(`pisquad is already up to date (v${currentVersion})`);
    return { updated: false, reason: "already latest" };
  }
  logger.info(`Updating pisquad v${currentVersion} → v${latestVersion}`);
  logger.info(`Updating pisquad via npm install -g (timeout ${NPM_TIMEOUT_MS / 1000}s)`);
  let result: ExecCaptureResult;
  try {
    result = await (opts.deps?.runNpmInstallGlobal ?? runNpmInstallGlobal)();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`self-update failed: ${message}`);
  }

  if (result.exitCode !== 0) {
    const combined = (result.stderr || result.stdout || "").trim();
    const snippet = combined.length > 800 ? `${combined.slice(0, 800)}…` : combined;
    throw new Error(
      `npm install -g @nicklin/pisquad@latest exited ${result.exitCode}${snippet ? `\n${snippet}` : ""}`,
    );
  }

  return { updated: true };
}

import type { Channels } from "../ui.js";
import { logger as defaultLogger } from "../logger.js";
import type { Logger } from "./types.js";
import { installCore } from "./core.js";
import { installCodegraph } from "./codegraph.js";
import { installEntire } from "./entire.js";

export type { PluginOptions } from "./types.js";

export interface InstallChannelsOptions {
  dryRun?: boolean;
  logger?: Logger;
}

/**
 * Run the channel installation in the documented order: core first (always),
 * then the optional channels the caller requested.
 *
 * Throws when any required step fails. Optional steps (codegraph init, entire
 * enable) already log warnings internally rather than throwing.
 */
export async function installChannels(target: string, channels: Channels, options: InstallChannelsOptions = {}): Promise<void> {
  const logger = options.logger ?? defaultLogger;

  await installCore(target, { dryRun: options.dryRun, logger });

  if (channels.codegraph) {
    await installCodegraph(target, { dryRun: options.dryRun, logger });
  }

  if (channels.entire) {
    await installEntire(target, { dryRun: options.dryRun, logger });
  }
}

export { installCore, installCodegraph, installEntire };

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { atomicWriteFile } from "../fs-safe.js";
import { join } from "node:path";
import { existsSync } from "node:fs";
import type { PluginOptions } from "./types.js";

/**
 * Core-only extension directories. Only the always-on extensions ship with
 * the core channel. Optional extensions (codegraph, entire) are copied by
 * their own channel plugins (`installCodegraph`, `installEntire`) so that
 * `--yes` (core only) never copies code whose `node_modules` we cannot ship.
 */
const EXTENSION_DIRS = new Set([
  "extensions/subagent",
  "extensions/wikilink-lint",
]);

/**
 * Copy the "core" payload (agents, skills, only the always-on extensions
 * subagent + wikilink-lint source trees).
 *
 * The optional codegraph / entire extensions are NOT copied here — they are
 * installed by their own channel plugins when the user passes `--with`. This
 * keeps the core payload stable per the PRD decision "core locked, codegraph /
 * entire optional", and avoids shipping codegraph source without its
 * `node_modules` (which would break `import typebox` at pi load time).
 */
export async function installCore(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const baseAsset = resolveAsset(".pi");

  const simpleDirs = ["agents", "skills"];
  for (const sub of simpleDirs) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      logger.warn(`Skipping missing asset directory: ${source}`);
      continue;
    }
    if (opts.dryRun) {
      copyDir(source, destination, { dryRun: true });
    } else {
      copyDir(source, destination);
    }
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  // Docs payload lives at assets/docs/ and is part of the core channel
  // (always installed). Consumers treat <target>/docs/ as the documentation
  // library template — see docs/conventions/.
  const docsSource = resolveAsset("docs");
  const docsDestination = join(target, "docs");
  const onSkip = (rel: string, reason: string): void => logger.warn(`Skipped ${rel} (${reason})`);
  if (!existsSync(docsSource)) {
    logger.warn(`Skipping missing asset directory: ${docsSource}`);
  } else if (opts.dryRun) {
    copyDir(docsSource, docsDestination, { dryRun: true });
    logger.info(`[dry-run] copy docs → docs`);
  } else {
    copyDir(docsSource, docsDestination, { onSkip });
    logger.info(`copied docs → docs`);
  }

  for (const sub of EXTENSION_DIRS) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      if (opts.dryRun) {
        logger.info(`[dry-run] skip missing: assets/.pi/${sub}`);
      } else {
        logger.warn(`Skipping missing asset directory: ${source}`);
      }
      continue;
    }
    const options: {
      filter: (_abs: string, rel: string) => boolean;
      dryRun?: boolean;
      onSkip?: (rel: string, reason: string) => void;
    } = {
      filter: (_abs: string, rel: string) => rel !== "node_modules" && rel !== "package-lock.json",
      onSkip: (rel: string, reason: string) => logger.warn(`Skipped ${rel} (${reason})`),
    };
    if (opts.dryRun) options.dryRun = true;
    copyDir(source, destination, options);
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  // Pin the .pi/.gitignore so users do not accidentally check node_modules in.
  const gitignorePath = join(target, ".pi", ".gitignore");
  if (opts.dryRun) {
    logger.info(`[dry-run] write ${gitignorePath}`);
  } else if (!existsSync(gitignorePath)) {
    atomicWriteFile(gitignorePath, "node_modules\n");
  }
}

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { atomicWriteFile } from "../fs-safe.js";
import { execFile } from "node:child_process";
import { copyFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import type { PluginOptions } from "./types.js";

const execFileAsync = promisify(execFile);

const NPM_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes
const INIT_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes
const EXEC_MAX_BUFFER = 64 * 1024 * 1024; // 64MB — large codegraphs can exceed 4MB default

/**
 * Install the codegraph extension into the target.
 *
 * The extension ships with a `node_modules/` directory that should NOT be
 * shipped to consumers (size, platform mismatch, npm registry churn). Instead
 * we copy the source files + package.json + .gitignore and then run
 * `npm install` against the package.json to materialise dependencies.
 */
export async function installCodegraph(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const source = resolveAsset(".pi/extensions/codegraph");
  const destination = join(target, ".pi", "extensions", "codegraph");
  const onSkip = (rel: string, reason: string): void => logger.warn(`Skipped ${rel} (${reason})`);

  if (!existsSync(source)) {
    logger.warn(`Missing codegraph asset directory: ${source}`);
    return;
  }

  // Copy everything except node_modules / package-lock.json (lock is rebuilt by npm install).
  if (opts.dryRun) {
    copyDir(source, destination, {
      dryRun: true,
      filter: (_abs, rel) => rel !== "node_modules" && rel !== "package-lock.json",
      onSkip,
    });
    logger.info(`[dry-run] npm install (skipped)`);
    logger.info(`[dry-run] codegraph init (skipped)`);
    return;
  }

  copyDir(source, destination, {
    filter: (_abs, rel) => rel !== "node_modules" && rel !== "package-lock.json",
    onSkip,
  });
  logger.info(`copied extensions/codegraph`);

  // Ensure .gitignore pins node_modules.
  const gitignore = join(destination, ".gitignore");
  if (!existsSync(gitignore)) {
    atomicWriteFile(gitignore, "node_modules\n");
  }

  // Ship the hand-curated codegraph.json (input to \`codegraph init\`) into the
  // target root. Never overwrite an existing one — the user may have customised it.
  const configSource = resolveAsset("codegraph.json");
  const configDestination = join(target, "codegraph.json");
  if (existsSync(configDestination)) {
    logger.info(`codegraph.json already present at ${configDestination}, skipping`);
  } else if (!existsSync(configSource)) {
    logger.warn(`Missing codegraph config asset: ${configSource}`);
  } else {
    copyFileSync(configSource, configDestination);
    logger.info(`copied codegraph.json → ${configDestination}`);
  }

  // Run npm install in the destination.
  try {
    logger.info(`running npm install (timeout ${NPM_TIMEOUT_MS / 1000}s)`);
    await execFileAsync("npm", ["install", "--no-audit", "--no-fund", "--loglevel=warn"], {
      cwd: destination,
      timeout: NPM_TIMEOUT_MS,
      maxBuffer: EXEC_MAX_BUFFER,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`codegraph npm install failed: ${message}`);
  }

  // codegraph init is best-effort: the user can run it manually later.
  if (!existsSync(join(target, ".codegraph"))) {
    try {
      logger.info(`running codegraph init (timeout ${INIT_TIMEOUT_MS / 1000}s)`);
      await execFileAsync("codegraph", ["init"], {
        cwd: target,
        timeout: INIT_TIMEOUT_MS,
        maxBuffer: EXEC_MAX_BUFFER,
      });
    } catch (error) {
      logger.warn(`codegraph init failed (non-fatal): ${error instanceof Error ? error.message : String(error)}`);
      logger.warn(`run \`codegraph init\` inside ${target} manually before using codegraph tools`);
    }
  } else {
    logger.info(`.codegraph already present, skipping init`);
  }
}

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import type { PluginOptions } from "./types.js";

const execFileAsync = promisify(execFile);

const ENABLE_TIMEOUT_MS = 30 * 1000; // 30s — entire enable should be fast

/**
 * Install the entire extension into the target.
 *
 * This plugin fixes the long-standing bash installer bug where selecting the
 * "entire" channel only ran `entire enable --agent pi` without first copying
 * the extension source directory, leaving consumers with a half-installed
 * extension. Both steps now happen here, in this order:
 *
 *   1. Copy assets/.pi/extensions/entire → <target>/.pi/extensions/entire
 *   2. Run `entire enable --agent pi` (idempotent, best-effort)
 */
export async function installEntire(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const source = resolveAsset(".pi/extensions/entire");
  const destination = join(target, ".pi", "extensions", "entire");

  if (!existsSync(source)) {
    logger.warn(`Missing entire asset directory: ${source}`);
    return;
  }

  if (opts.dryRun) {
    copyDir(source, destination, { dryRun: true });
    logger.info(`[dry-run] entire enable --agent pi (skipped)`);
    return;
  }

  // Step 1: copy the extension directory (the bug fix).
  copyDir(source, destination, {
    onSkip: (rel: string, reason: string) => logger.warn(`Skipped ${rel} (${reason})`),
  });
  logger.info(`copied extensions/entire → ${destination}`);

  // Step 2: register with entire (best-effort — entire may not be installed yet).
  try {
    logger.info(`running entire enable --agent pi`);
    await execFileAsync("entire", ["enable", "--agent", "pi"], {
      cwd: target,
      timeout: ENABLE_TIMEOUT_MS,
      maxBuffer: 4 * 1024 * 1024,
    });
  } catch (error) {
    logger.warn(`entire enable --agent pi failed (non-fatal): ${error instanceof Error ? error.message : String(error)}`);
    logger.warn(`re-run \`entire enable --agent pi\` inside ${target} once Entire CLI is installed`);
  }
}

import { run } from "./main.js";

run(process.argv).catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

import { Command } from "commander";
import { readCliVersion } from "./lib/version.js";
import { installCommand } from "./commands/install.js";
import { upgradeCommand } from "./commands/upgrade.js";
import { versionCommand } from "./commands/version.js";
import { helpCommand } from "./commands/help.js";

export const program = new Command();

program
  .name("pisquad")
  .description("Install and upgrade the pi-squad development foundation")
  .version(readCliVersion(), "-V, --version", "Print version and exit");

program
  .command("install [path]")
  .description("Install pi-squad into the target directory (default: cwd)")
  .option("-y, --yes", "Skip prompts, install core only")
  .option("--with <channels>", "Comma-separated list of optional channels to install")
  .option("--without <channels>", "Comma-separated list of optional channels to skip")
  .option("--all", "Install every optional channel")
  .option("--dry-run", "Preview changes without writing anything")
  .action(async (pathArg: string | undefined, options: Record<string, unknown>) => {
    await installCommand({
      target: pathArg,
      yes: Boolean(options.yes),
      with: typeof options.with === "string" ? options.with : undefined,
      without: typeof options.without === "string" ? options.without : undefined,
      all: Boolean(options.all),
      dryRun: Boolean(options.dryRun),
    });
  });

program
  .command("upgrade [path]")
  .description("Upgrade an existing pi-squad install to match the current assets")
  .option("--prune", "Delete files in target that are no longer in assets (backed up first)")
  .option("--dry-run", "Preview the upgrade plan without writing anything")
  .option("--no-self", "Skip the CLI self-update stage")
  .option("--with <channels>", "Comma-separated list of optional channels to enable")
  .option("--without <channels>", "Comma-separated list of optional channels to disable")
  .option("-y, --yes", "Accept defaults without prompts (skip install channel prompts and upgrade interactive prompts)")
  .option("--interactive", "Force per-file interactive prompts (requires a tty)")
  .option("--no-interactive", "Skip interactive prompts even on a tty (batch adopt + backup)")
  .action(async (pathArg: string | undefined, options: Record<string, unknown>) => {
    // Commander's `--no-self` flag toggles `options.self` to `false`; the
    // conventional `options.noSelf` key is never set, so we check the negated
    // property directly here.
    const noSelf =
      options.noSelf === true ||
      options.self === false ||
      process.env.PISQUAD_NO_SELF === "1";
    // Interactive flag parsing: `--interactive` sets options.interactive = true;
    // `--no-interactive` sets options.interactive = false. We track which
    // case the user took so the decision layer can warn when the user
    // explicitly asked for non-interactive but we silently fell back.
    const interactive =
      options.interactive === true
        ? true
        : options.interactive === false
          ? false
          : undefined;
    const interactiveSetByUser = interactive !== undefined;
    await upgradeCommand({
      target: pathArg,
      prune: Boolean(options.prune),
      dryRun: Boolean(options.dryRun),
      noSelf,
      with: typeof options.with === "string" ? options.with : undefined,
      without: typeof options.without === "string" ? options.without : undefined,
      yes: Boolean(options.yes),
      interactive,
      interactiveSetByUser,
    });
  });

program
  .command("version")
  .description("Print CLI and assets versions")
  .action(() => {
    versionCommand();
  });

program
  .command("help [command]")
  .description("Show help for pisquad or one of its subcommands")
  .action((commandName?: string) => {
    helpCommand(commandName);
  });

// No-argument invocation forwards to install.
program.action(async () => {
  const { defaultCommand } = await import("./commands/default.js");
  await defaultCommand();
});

export async function run(argv: string[]): Promise<void> {
  await program.parseAsync(argv);
}

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { resolveTarget, stateFile } from "../lib/paths.js";
import { which } from "../lib/env.js";
import { logger } from "../lib/logger.js";
import { atomicWriteFile } from "../lib/fs-safe.js";
import { decideChannels, type Channels } from "../lib/ui.js";
import { writeState, readState } from "../lib/version.js";
import { installChannels } from "../lib/plugins/index.js";

export interface InstallOptions {
  target?: string;
  yes?: boolean;
  with?: string;
  without?: string;
  all?: boolean;
  dryRun?: boolean;
}

interface EnvironmentProbe {
  node: boolean;
  npm: boolean;
  codegraph: boolean;
  entire: boolean;
}

function probeEnvironment(): EnvironmentProbe {
  return {
    node: which("node") !== null,
    npm: which("npm") !== null,
    codegraph: which("codegraph") !== null,
    entire: which("entire") !== null,
  };
}

function paintInstalled(channel: string): string {
  return `\u2713 ${channel}`;
}

function printChannelSummary(channels: Channels): void {
  logger.info("Channels installed:");
  logger.info(`  ${paintInstalled("core")} (always)`);
  logger.info(`  ${channels.codegraph ? paintInstalled("codegraph") : "  codegraph"}`);
  logger.info(`  ${channels.entire ? paintInstalled("entire") : "  entire"}`);
}

function appendGitignoreRule(target: string): void {
  const gitignore = join(target, ".gitignore");
  if (!existsSync(gitignore)) return;
  const existing = readFileSync(gitignore, "utf8");
  if (existing.includes(".pi/.pisquad/")) return;
  const sep = existing.endsWith("\n") ? "" : "\n";
  const next = `${existing}${sep}.pi/.pisquad/\n`;
  // Atomic so a crash mid-write cannot truncate the user's existing .gitignore.
  atomicWriteFile(gitignore, next);
  logger.info("appended .pi/.pisquad/ to .gitignore");
}

/**
 * Full install pipeline. The Commander layer (main.ts) routes here.
 *
 * Behavioural contract:
 * - Refuses to run when <target>/.pi/.pisquad/state.json already exists; the
 *   user must use `pisquad upgrade` instead.
 * - Refuses when node or npm are missing (hard requirement for core).
 * - Refuses only when an optional channel is requested AND its host CLI is
 *   missing.
 * - Honors the non-interactive contract: no tty + no flags → core only, exit 0.
 * - Honors --dry-run end-to-end (no writes, including state.json).
 */
export async function installCommand(options: InstallOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const env = probeEnvironment();
  const dryRun = options.dryRun === true;

  logger.info(`pisquad install → ${target}${dryRun ? " (dry-run)" : ""}`);

  if (!env.node || !env.npm) {
    logger.error("node and npm are required to install pi-squad");
    logger.error("install Node.js 18+ from https://nodejs.org/ (which includes npm) and try again");
    process.exitCode = 1;
    return;
  }

  const existing = readState(target);
  if (existing) {
    logger.error("pi-squad is already installed in this directory");
    logger.error(`state file: ${stateFile(target)}`);
    logger.error("re-run with \`pisquad upgrade\` to update an existing installation");
    logger.error("(upgrade lands in stage 2; for now, remove the state file or pick another target)");
    process.exitCode = 1;
    return;
  }

  const channels = await decideChannels({
    all: options.all,
    with: options.with,
    without: options.without,
    yes: options.yes,
    target,
  });

  // Gate optional channels on their host CLI availability.
  if (channels.codegraph && !env.codegraph) {
    logger.error("channel 'codegraph' was requested but the codegraph CLI is not on PATH");
    logger.error("install it from https://github.com/... (or omit 'codegraph' from --with / --all)");
    process.exitCode = 1;
    return;
  }
  if (channels.entire && !env.entire) {
    logger.error("channel 'entire' was requested but the entire CLI is not on PATH");
    logger.error("install it from https://entire.io (or omit 'entire' from --with / --all)");
    process.exitCode = 1;
    return;
  }

  try {
    await installChannels(target, channels, { dryRun });
  } catch (error) {
    logger.error(`install failed: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
    return;
  }

  if (dryRun) {
    logger.info("DRY RUN — no changes made");
    return;
  }

  writeState(target, { channels });
  appendGitignoreRule(target);

  printChannelSummary(channels);
  logger.success("install complete");
  logger.info(`state file: ${stateFile(target)}`);
}

import { logger } from "../lib/logger.js";

/**
 * Default command handler.
 *
 * Commander's "no subcommand" hook is wired here so that running `pisquad`
 * with no arguments behaves like `pisquad install`.
 */
export async function defaultCommand(): Promise<void> {
  logger.info("default command → install");
  const { installCommand } = await import("./install.js");
  await installCommand({});
}

import { program } from "../main.js";

/**
 * Print global or per-command help.
 * Falls back to commander's built-in help when no command name is given.
 */
export function helpCommand(commandName?: string): void {
  if (!commandName) {
    program.outputHelp();
    return;
  }

  const subcommand = program.commands.find((cmd) => cmd.name() === commandName || cmd.aliases().includes(commandName));
  if (!subcommand) {
    console.error(`Unknown command: ${commandName}`);
    program.outputHelp();
    return;
  }
  subcommand.outputHelp();
}

import { readCliVersion, resolveAssetsVersion } from "../lib/version.js";

/**
 * Print CLI and assets versions.
 * Format: `pisquad <cliVersion> (assets <version>)`
 */
export function versionCommand(): void {
  const cliVersion = readCliVersion();
  const assetsVersion = resolveAssetsVersion(cliVersion);
  console.log(`pisquad ${cliVersion} (assets ${assetsVersion})`);
}

